// Runs the staff dashboard's own matching code on evaluations generated by seed_sprint_heroes.py:
// ALG-14 (frontend/src/lib/matching/contactOpportunities.js), ALG-10 (leadProjectMatching.js) and
// the HU 14 comparison (leadComparison.js). Input: a JSON file
//   { scenarios: [{ key, evaluations, projects, project_id, compare: [user_id, user_id] }] }
// with evaluations shaped like normalizeEvaluation() returns them. Output, per scenario key:
//   { opportunities: [{ user_id, primary, rank, triggers }], matches: { user_id: { previous, latest } },
//     comparison: [{ user_id, classification, reachesMin, affinity }] }
import { readFileSync } from "node:fs";
import { register } from "node:module";

// The frontend's lib/ uses extensionless imports, which Vite resolves and plain Node does not.
register("data:text/javascript," + encodeURIComponent(`
export async function resolve(specifier, context, next) {
  try {
    return await next(specifier, context);
  } catch (error) {
    if (error.code === "ERR_MODULE_NOT_FOUND" && specifier.startsWith(".") && !/\\.[cm]?js$/.test(specifier)) {
      return next(specifier + ".js", context);
    }
    throw error;
  }
}`));

const lib = (path) => import(new URL(`../../frontend/src/lib/matching/${path}`, import.meta.url).href);
const { detectContactOpportunities } = await lib("contactOpportunities.js");
const { matchLeadToProjects } = await lib("leadProjectMatching.js");
const { buildLeadProjectComparison } = await lib("leadComparison.js");

function summarizeMatch(evaluation, project) {
  if (!evaluation) return null;
  const { matches, excluidos } = matchLeadToProjects(evaluation, [project]);
  const match = matches[0] || excluidos[0] || null;
  return match && {
    clasificacion: match.clasificacion || null,
    afinidad: match.afinidad ?? null,
    motivo_exclusion: match.motivo_exclusion || null,
    alcanza_precio_min: match.evidencia?.alcanza_precio_min === true,
    classification: evaluation.result?.classification || null,
    score: evaluation.result?.score ?? null,
  };
}

const { scenarios } = JSON.parse(readFileSync(process.argv[2], "utf-8"));
const output = {};
for (const { key, evaluations, projects, project_id, compare } of scenarios) {
  const project = projects.find((item) => item.id === project_id);
  const byLead = new Map();
  for (const evaluation of evaluations) {
    if (!byLead.has(evaluation.user_id)) byLead.set(evaluation.user_id, []);
    byLead.get(evaluation.user_id).push(evaluation);
  }
  const ordered = (userId) => [...(byLead.get(userId) || [])].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
  const opportunities = detectContactOpportunities(evaluations, projects).map((item) => ({
    user_id: item.lead.user_id,
    primary: item.primary.type,
    rank: item.primary.rank,
    triggers: item.triggers.map((trigger) => `${trigger.type}:${trigger.project?.id || ""}`),
  }));
  const matches = Object.fromEntries(compare.map((userId) => {
    const [latest, previous] = ordered(userId);
    return [userId, { latest: summarizeMatch(latest, project), previous: summarizeMatch(previous, project) }];
  }));
  const comparison = buildLeadProjectComparison(compare.map((userId) => ordered(userId)[0]), project).map((row) => ({
    user_id: row.lead.user_id,
    classification: row.classification,
    reachesMin: row.capacity.reachesMin,
    affinity: row.affinity.classification,
  }));
  output[key] = { opportunities, matches, comparison };
}
process.stdout.write(JSON.stringify(output));
